<template>
  <div class="customer-management">
    <!-- 页面标题与操作按钮 -->
    <div class="header">
      <h2>客户管理</h2>
      <el-button type="primary" @click="handleAdd">+ 新增客户</el-button>
    </div>

    <!-- 搜索与筛选区域 -->
    <el-card class="filter-card" shadow="never">
      <el-form :inline="true" :model="searchForm" size="small">
        <el-form-item label="客户名称">
          <el-input v-model="searchForm.name" placeholder="请输入" clearable />
        </el-form-item>
        <el-form-item label="联系人">
          <el-input v-model="searchForm.contact" placeholder="请输入" clearable />
        </el-form-item>
        <el-form-item label="联系电话">
          <el-input v-model="searchForm.phone" placeholder="请输入" clearable />
        </el-form-item>
        <el-form-item label="状态">
          <el-select v-model="statusFilter" placeholder="全部" clearable style="width: 120px">
            <el-option label="启用" value="active" />
            <el-option label="禁用" value="inactive" />
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="handleSearch">查询</el-button>
          <el-button @click="resetSearch">重置</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <!-- 客户列表表格 -->
    <el-card class="table-card" shadow="never">
      <!-- 空数据兜底 -->
      <div v-if="filteredData.length === 0" class="empty-table">
        暂无符合条件的客户数据
      </div>
      <!-- 表格：仅当有数据时渲染 -->
      <el-table 
        v-else 
        :data="paginatedData" 
        border 
        stripe 
        style="width: 100%"
        :key="`table-${currentPage}-${pageSize}`" 
      >
        <el-table-column prop="id" label="客户ID" width="80" />
        <el-table-column prop="name" label="客户名称" min-width="120" />
        <el-table-column prop="contact" label="联系人" width="100" />
        <el-table-column prop="phone" label="联系电话" width="120" />
        <el-table-column prop="email" label="邮箱" min-width="150" />
        <el-table-column prop="address" label="地址" min-width="180" show-overflow-tooltip />
        <el-table-column prop="createTime" label="创建时间" width="160" />
        <el-table-column prop="status" label="状态" width="80">
          <template v-slot:default="scope">
            <el-tag :type="scope.row.status === 'active' ? 'success' : 'danger'" size="small">
              {{ scope.row.status === 'active' ? '启用' : '禁用' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="200" fixed="right">
          <template v-slot:default="scope">
            <el-button type="text" size="small" @click="handleEdit(scope.row)">编辑</el-button>
            <el-button type="text" size="small" @click="handleView(scope.row)">详情</el-button>
            <el-button type="text" size="small" style="color: #f56c6c" @click="handleDelete(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页组件：仅当有数据时渲染 -->
    </el-card>

    <!-- 新增/编辑客户对话框 -->
    <el-dialog
      :title="dialogType === 'add' ? '新增客户' : '编辑客户'"
      v-model:visible="dialogVisible"
      width="500px"
      @close="resetForm"
    >
      <el-form ref="customerForm" :model="currentCustomer" :rules="formRules" label-width="100px">
        <el-form-item label="客户名称" prop="name">
          <el-input v-model="currentCustomer.name" placeholder="请输入客户名称" />
        </el-form-item>
        <el-form-item label="联系人" prop="contact">
          <el-input v-model="currentCustomer.contact" placeholder="请输入联系人" />
        </el-form-item>
        <el-form-item label="联系电话" prop="phone">
          <el-input v-model="currentCustomer.phone" placeholder="请输入联系电话" />
        </el-form-item>
        <el-form-item label="邮箱" prop="email">
          <el-input v-model="currentCustomer.email" placeholder="请输入邮箱" />
        </el-form-item>
        <el-form-item label="地址" prop="address">
          <el-input v-model="currentCustomer.address" type="textarea" rows="2" placeholder="请输入地址" />
        </el-form-item>
        <el-form-item label="状态" prop="status">
          <el-radio-group v-model="currentCustomer.status">
            <el-radio label="active">启用</el-radio>
            <el-radio label="inactive">禁用</el-radio>
          </el-radio-group>
        </el-form-item>
      </el-form>
      <template v-slot:footer>
        <span class="dialog-footer">
          <el-button @click="dialogVisible = false">取 消</el-button>
          <el-button type="primary" @click="saveCustomer">确 定</el-button>
        </span>
      </template>
    </el-dialog>

    <!-- 查看详情对话框 -->
    <el-dialog title="客户详情" v-model:visible="detailVisible" width="500px">
      <el-descriptions :column="1" border>
        <el-descriptions-item label="客户ID">{{ viewCustomer.id || '-' }}</el-descriptions-item>
        <el-descriptions-item label="客户名称">{{ viewCustomer.name || '-' }}</el-descriptions-item>
        <el-descriptions-item label="联系人">{{ viewCustomer.contact || '-' }}</el-descriptions-item>
        <el-descriptions-item label="联系电话">{{ viewCustomer.phone || '-' }}</el-descriptions-item>
        <el-descriptions-item label="邮箱">{{ viewCustomer.email || '-' }}</el-descriptions-item>
        <el-descriptions-item label="地址">{{ viewCustomer.address || '-' }}</el-descriptions-item>
        <el-descriptions-item label="创建时间">{{ viewCustomer.createTime || '-' }}</el-descriptions-item>
        <el-descriptions-item label="状态">
          <el-tag :type="viewCustomer.status === 'active' ? 'success' : 'danger'">
            {{ viewCustomer.status === 'active' ? '启用' : viewCustomer.status === 'inactive' ? '禁用' : '-' }}
          </el-tag>
        </el-descriptions-item>
      </el-descriptions>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'CustomerManagement',
  data() {
    return {
      // 模拟客户数据
      allCustomers: [
        {
          id: 1,
          name: '深圳科技有限公司',
          contact: '张三',
          phone: '13800138001',
          email: 'zhangsan@tech.com',
          address: '广东省深圳市南山区科技园',
          createTime: '2024-01-15 10:30',
          status: 'active'
        },
        {
          id: 2,
          name: '上海贸易有限公司',
          contact: '李四',
          phone: '13800138002',
          email: 'lisi@trade.com',
          address: '上海市浦东新区陆家嘴',
          createTime: '2024-02-20 14:20',
          status: 'active'
        },
        {
          id: 3,
          name: '北京咨询服务有限公司',
          contact: '王五',
          phone: '13800138003',
          email: 'wangwu@consult.com',
          address: '北京市朝阳区CBD',
          createTime: '2024-03-10 09:15',
          status: 'inactive'
        }
      ],
      searchForm: {
        name: '',
        contact: '',
        phone: ''
      },
      statusFilter: '', // 状态筛选，空表示全部
      currentPage: 1,
      pageSize: 10,
      dialogVisible: false,
      dialogType: 'add', // 'add' 或 'edit'
      currentCustomer: this.getEmptyCustomer(),
      detailVisible: false,
      viewCustomer: {},
      formRules: {
        name: [{ required: true, message: '请输入客户名称', trigger: 'blur' }],
        contact: [{ required: true, message: '请输入联系人', trigger: 'blur' }],
        phone: [
          { required: true, message: '请输入联系电话', trigger: 'blur' },
          { pattern: /^1[3-9]\d{9}$/, message: '请输入正确的手机号', trigger: 'blur' }
        ],
        email: [
          { required: true, message: '请输入邮箱', trigger: 'blur' },
          { type: 'email', message: '请输入正确的邮箱地址', trigger: 'blur' }
        ],
        address: [{ required: true, message: '请输入地址', trigger: 'blur' }],
        status: [{ required: true, message: '请选择状态', trigger: 'change' }]
      }
    }
  },
  computed: {
    // 根据搜索条件和状态过滤数据
    filteredData() {
      // 深拷贝避免原数组被修改
      const filtered = JSON.parse(JSON.stringify(this.allCustomers)).filter(item => {
        const matchName = !this.searchForm.name || item.name.includes(this.searchForm.name)
        const matchContact = !this.searchForm.contact || item.contact.includes(this.searchForm.contact)
        const matchPhone = !this.searchForm.phone || item.phone.includes(this.searchForm.phone)
        const matchStatus = !this.statusFilter || item.status === this.statusFilter
        return matchName && matchContact && matchPhone && matchStatus
      })
      console.log('过滤后数据:', filtered)
      return filtered
    },
    // 分页后的数据（增加容错）
    paginatedData() {
      if (this.filteredData.length === 0) return []
      const start = (this.currentPage - 1) * this.pageSize
      const end = start + this.pageSize
      const paginated = this.filteredData.slice(start, end)
      console.log('分页后数据:', paginated, '起始索引:', start, '结束索引:', end)
      return paginated
    }
  },
  methods: {
    // 获取空客户对象
    getEmptyCustomer() {
      return {
        id: null,
        name: '',
        contact: '',
        phone: '',
        email: '',
        address: '',
        createTime: '',
        status: 'active'
      }
    },
    // 搜索
    handleSearch() {
      this.currentPage = 1
      // 强制触发视图更新
      this.$forceUpdate()
    },
    // 重置搜索
    resetSearch() {
      this.searchForm = { name: '', contact: '', phone: '' }
      this.statusFilter = ''
      this.currentPage = 1
      this.$forceUpdate()
    },
    // 新增
    handleAdd() {
      this.dialogType = 'add'
      this.currentCustomer = this.getEmptyCustomer()
      this.dialogVisible = true
    },
    // 编辑
    handleEdit(row) {
      this.dialogType = 'edit'
      this.currentCustomer = { ...row }
      this.dialogVisible = true
    },
    // 查看详情
    handleView(row) {
      this.viewCustomer = { ...row }
      this.detailVisible = true
    },
    // 删除
    handleDelete(row) {
      this.$confirm(`确认删除客户“${row.name}”吗？`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        const index = this.allCustomers.findIndex(c => c.id === row.id)
        if (index !== -1) {
          this.allCustomers.splice(index, 1)
          // 分页容错：删除后当前页无数据则跳上一页
          if (this.paginatedData.length === 0 && this.currentPage > 1) {
            this.currentPage--
          }
        }
        this.$message.success('删除成功')
      }).catch(() => {})
    },
    // 保存
    saveCustomer() {
      this.$refs.customerForm.validate(valid => {
        if (valid) {
          if (this.dialogType === 'add') {
            const newId = Math.max(...this.allCustomers.map(c => c.id), 0) + 1
            const now = new Date()
            const createTime = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`
            const newCustomer = {
              ...this.currentCustomer,
              id: newId,
              createTime
            }
            this.allCustomers.push(newCustomer)
            this.$message.success('新增成功')
          } else {
            const index = this.allCustomers.findIndex(c => c.id === this.currentCustomer.id)
            if (index !== -1) {
              this.allCustomers[index] = { ...this.currentCustomer, createTime: this.allCustomers[index].createTime }
            }
            this.$message.success('编辑成功')
          }
          this.dialogVisible = false
          // 保存后刷新表格
          this.$forceUpdate()
        }
      })
    },
    // 重置表单
    resetForm() {
      if (this.$refs.customerForm) {
        this.$refs.customerForm.clearValidate()
      }
      this.currentCustomer = this.getEmptyCustomer()
    },
    // 分页页码改变
    handlePageChange(page) {
      this.currentPage = page
      // 页码切换时强制更新视图
      this.$forceUpdate()
    },
    // 每页条数改变
    handleSizeChange(size) {
      this.pageSize = size
      this.currentPage = 1
      this.$forceUpdate()
    }
  },
  mounted() {
    // 延迟打印，确保计算属性已完全执行
    setTimeout(() => {
      console.log('初始化 - 全部数据:', this.allCustomers)
      console.log('初始化 - 过滤后数据:', this.filteredData)
      console.log('初始化 - 分页后数据:', this.paginatedData)
    }, 100)
  }
}
</script>

<style scoped>
.customer-management {
  padding: 20px;
}
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}
.filter-card {
  margin-bottom: 20px;
}
.table-card {
  margin-bottom: 20px;
}
.pagination {
  margin-top: 20px;
  text-align: right;
}
/* 空表格样式 */
.empty-table {
  padding: 40px 0;
  text-align: center;
  color: #999;
  font-size: 14px;
}
</style>